        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Il documento di finanza pubblica scontenta tutti",
        "testo_it": "Il nuovo documento di finanza pubblica italiano suscita critiche da sindacati e Confindustria.",
        "priorita": "Bassa",
        "id_gruppo": 29,
        "link": "https://ilmanifesto.it/il-documento-di-finanza-pubblica-scontenta-tutti",
        "orario": "00:05",
